import Foundation
import XCTest
@testable import BridgeyMac

/// A session recorded between two Bridgey session clients (rust/client, the core of the Windows app) after pairing:
/// a phone's notifications and codes messages, and the Windows side's answers. Every frame is checked with this app's
/// envelope tags and AES-GCM, and the notification posts with its own presentation decoder (alert and quiet), so the
/// Windows reader and the Mac agree on what is quiet. Generated by rust/client/src/vectors.rs.
final class SessionClientNotificationsVectorTests: XCTestCase {
    private struct Frame {
        let from: String
        let message: PairingMessage
    }

    private func load() throws -> (sessionKey: Data, frames: [Frame]) {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/session-client-notifications-v1.json")
            .standardizedFileURL
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        var frames: [Frame] = []
        for raw in try XCTUnwrap(object["frames"] as? [[String: Any]]) {
            frames.append(Frame(from: try XCTUnwrap(raw["from"] as? String), message: try decodeProtocolMessage(Data(try XCTUnwrap(raw["line"] as? String).utf8))))
        }
        return (try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["sessionKey"] as? String))), frames)
    }

    func testEveryFrameIsTaggedAndPostsDecodeAlertAndQuiet() throws {
        let (key, frames) = try load()
        var ids: [String: String] = [:]
        for frame in frames where frame.message.kind == "pairing.offer" || frame.message.kind == "pairing.answer" {
            ids[frame.from] = frame.message.deviceId
        }
        let envelopeKey = SessionSecurity.envelopeKey(sessionKey: key)
        var presentations: [NotificationPresentation] = []
        for frame in frames where !frame.message.kind.hasPrefix("pairing.") {
            let sender = try XCTUnwrap(ids[frame.from])
            XCTAssertTrue(SessionSecurity.tagMatches(envelopeKey: envelopeKey, senderDeviceID: sender, message: frame.message), frame.message.kind)
            guard let ciphertext = frame.message.ciphertext else { continue }
            let plaintext = try decrypt(nonce: try XCTUnwrap(frame.message.nonce), ciphertext: ciphertext, key: key)
            if frame.message.kind == "notifications.post" {
                presentations.append(try XCTUnwrap(NotificationPresentation.decode(plaintext, negotiated: true)))
            }
        }
        XCTAssertEqual(presentations, [.alert, .quiet])
    }
}
